import org.junit.Test;
import static org.junit.Assert.*;
import java.io.IOException;

public class TextNodeTest {

    @Test
    public void createTextnodeWithEmptyString_ReturnsBlankTextNode() {
        String text = "";
        TextNode textNode = new TextNode(text);
        assertTrue(textNode.isBlank());
    }

    @Test
    public void createTextnodeWithSingleChar_ReturnsNonBlankTextNode() {
        String text = "a";
        TextNode textNode = new TextNode(text);
        assertFalse(textNode.isBlank());
    }

    @Test
    public void splitTextAtOffset_ReturnsNewTextNodeWithRemainingContent() throws IOException {
        String text = "Hello World!";
        int offset = 6;
        TextNode textNode = new TextNode(text);
        TextNode newTextNode = textNode.splitText(offset);
        assertEquals("World!", newTextNode.text());
    }

    @Test
    public void cloneTextNode_ReturnsNewTextNodeWithSameContent() {
        String text = "Hello World!";
        TextNode textNode = new TextNode(text);
        TextNode clonedTextNode = textNode.clone();
        assertEquals(text, clonedTextNode.text());
    }

    @Test
    public void createFromEncodedText_ReturnsTextNodeWithUnencodedContent() throws IOException {
        String encodedText = "&lt;Hello&gt;";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertEquals("&lt;Hello&gt;", textNode.toString());
    }

    @Test
    public void normaliseWhitespace_SplittingCharsAndSpaces() {
        String text = "   Hello, World!  ";
        String expectedText = "Hello, World!";
        String actualText = TextNode.normaliseWhitespace(text);
        assertEquals(expectedText, actualText);
    }
}
